        x_in = [x_in]

    results = []
    for s in x_in:
        parts = get_ansi_parts(s)
        logical_chars = []
        char_to_part_idx = []
        for i, part in enumerate(parts):
            if not (part.startswith('\033[') and (part.endswith('m') or part.endswith('K'))):
                for char in part:
