                else:
                    # Approximate CMC as a weighted Euclidean in Lab space
                    # In a real scenario, a full CMC formula would be used.
                    d = np.sqrt((c1[i,0]-c2[j,0])**2 + (c1[i,1]-c2[j,1])**2 + (c1[i,2]-c2[j,2])**2)
